        ["RTG-SPEC-001"] = new("RTG-SPEC-001", "Unsupported specification version", ErrorSeverity.Error, false, "The document declares a specVersion whose major version this engine does not support.", "Upgrade the engine, or write the document against a supported specVersion (see `rtogtor version`)."),
        ["RTG-VAL-001"] = new("RTG-VAL-001", "Invalid value for logical type", ErrorSeverity.Error, false, "A value is not a valid encoding of its logical type as defined in specs/values.md.", "Correct the value. The message names the type and the reason."),
